cd /app && python3 - <<'EOF'
t=open('transcript.txt').read().split('\n')
idx=[i for i,l in enumerate(t) if l.startswith('>')]
for a,b in zip(idx,idx[1:]):
    mid=[x for x in t[a+1:b] if x.strip()]
    if not mid: print('NO OUTPUT between',repr(t[a]),repr(t[b]),a,b)
# parser-error style responses
for i,l in enumerate(t):
    if any(k in l for k in ("I don't know the word",'That sentence','You used the word','not a verb','beg your pardon')):
        print('ERR',i,repr(l))
EOF
